const DB='touchline.match-records.v2';
function open(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('records',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function saveRecord(id,record){const db=await open();try{await new Promise((resolve,reject)=>{const tx=db.transaction('records','readwrite');tx.objectStore('records').put({id,...record});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Replay storage was interrupted.'));});}finally{db.close();}}
export async function getRecord(id){const db=await open();try{return await new Promise((resolve,reject)=>{const r=db.transaction('records').objectStore('records').get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error);});}finally{db.close();}}
export async function allRecords(prefix){const db=await open();try{return await new Promise((resolve,reject)=>{const r=db.transaction('records').objectStore('records').getAll();r.onsuccess=()=>resolve(r.result.filter(row=>row.id.startsWith(prefix+':')&&row.definition));r.onerror=()=>reject(r.error);});}finally{db.close();}}
export async function putRecords(records){const db=await open();try{await new Promise((resolve,reject)=>{const tx=db.transaction('records','readwrite');for(const row of records)tx.objectStore('records').put(row);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Replay import interrupted.'));});}finally{db.close();}}
export async function latestBackup(prefix){const db=await open();try{return await new Promise((resolve,reject)=>{const r=db.transaction('records').objectStore('records').getAll();r.onsuccess=()=>resolve(r.result.filter(row=>row.id.startsWith(prefix+':backup:')&&row.backup).sort((a,b)=>String(b.backup.createdAt).localeCompare(String(a.backup.createdAt)))[0]?.backup||null);r.onerror=()=>reject(r.error);});}finally{db.close();}}
